// План specs/dashboard.md 1.1–1.2 (кейсы DB-01, DB-02). Admin, компания «test». Только просмотр (@prod-safe).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import { Lang, expectClearViewBlockRemoved, expectSalesJobsRightAfterGreeting, openDashboard } from './dashboard-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Дашборд на телефоне: блока «A clear view of your day» нет (#b6cecf04)', () => {
  const cases: { lang: Lang; label: string }[] = [
    { lang: 'en', label: 'EN' },
    { lang: 'he', label: 'HE' },
  ];

  for (const { lang, label } of cases) {
    test(`Phone dashboard ${label}: no "A clear view of your day" block, Sales & Jobs right after greeting, Schedule in bottom nav #b6cecf04 @mobile @prod-safe`, async ({ page }) => {
      await openDashboard(page, lang);

      // Т1: блока и «Open schedule» нет («מה רצוי»: להסיר את הבלוק בגרסת המובייל).
      await expectClearViewBlockRemoved(page);

      // П1: под карточкой приветствия сразу график (комментарий программиста).
      await expectSalesJobsRightAfterGreeting(page, lang);

      // С2: расписание доступно из нижней навигации.
      const scheduleNav = page.locator('a[href="/schedule"]:visible');
      await expect(scheduleNav.first()).toBeVisible();
      if (lang === 'en') await expect(scheduleNav.first()).toContainText('Schedule');
    });
  }
});
